INSERT INTO chain_analysis (chain, take, sentiment, trend, updated_at, sources, profile)
VALUES (
  'ADI',
  'ADI has retained most of its small TVL base, which is better than a launch spike followed by immediate collapse. However, the large volume and fee figures sit beside very low activity reported by L2BEAT and a sharp monthly volume decline. That mismatch means we cannot yet say institutional adoption or repeat users caused the result. The fairest call is middling: operating and funded, but not yet proven.',
  'mixed',
  'ADI is operating and middling. It retained 93.69% of peak TVL and reports substantial aggregate volume and fees, but monthly volume fell sharply and independent activity remains low. The chain is too new and the metrics are too inconsistent to call it a durable success. The next lifecycle step is proving that named institutions generate repeated transactions and fees without relying on unlocks or centralized intervention.',
  '2026-08-03',
  '[{"id":"source:adi:overview","title":"ADI Foundation overview","url":"https://www.adi.foundation/","publisher":"ADI Foundation","source_role":"primary","tier":"B","checked_at":"2026-08-03T19:45:03.000Z","evidence_locator":"Current institutional-network positioning and documented ecosystem relationships."},{"id":"source:adi:mainnet","title":"ADI Network contracts","url":"https://docs.adi.foundation/how-to-start/network-contracts","publisher":"ADI Foundation","source_role":"primary","tier":"B","checked_at":"2026-08-03T19:45:03.000Z","evidence_locator":"Current mainnet core, bridge and governance contract addresses."},{"id":"source:adi:components","title":"ADI Network components","url":"https://docs.adi.foundation/adi-network-components/overview","publisher":"ADI Foundation","source_role":"primary","tier":"B","checked_at":"2026-08-03T19:45:03.000Z","evidence_locator":"Current execution, proving and active-development statements."},{"id":"source:adi:utility","title":"ADI token utility","url":"https://docs.adi.foundation/adi-token/adi-token-utility","publisher":"ADI Foundation","source_role":"primary","tier":"B","checked_at":"2026-08-03T19:45:03.000Z","evidence_locator":"Documented gas, staking and ecosystem utility claims."},{"id":"source:adi:tokenomics","title":"ADI tokenomics overview","url":"https://docs.adi.foundation/adi-token/adi-tokenomics-overview","publisher":"ADI Foundation","source_role":"primary","tier":"B","checked_at":"2026-08-03T19:45:03.000Z","evidence_locator":"Genesis supply, allocations, cliffs and monthly unlock schedule."},{"id":"source:adi:l2beat","title":"ADI risk analysis","url":"https://l2beat.com/scaling/projects/adi","publisher":"L2BEAT","source_role":"independent","tier":"A","checked_at":"2026-08-03T19:45:03.000Z","evidence_locator":"Current Stage 0, operator, multisig, upgrade, activity and liveness panels."},{"id":"source:adi:tvl","title":"ADI historical TVL API","url":"https://api.llama.fi/v2/historicalChainTvl/ADI","publisher":"DefiLlama","source_role":"independent","tier":"B","checked_at":"2026-08-03T19:45:03.000Z","evidence_locator":"Latest and maximum points in the returned daily TVL series."},{"id":"source:adi:volume","title":"ADI DEX volume API","url":"https://api.llama.fi/overview/dexs/ADI?dataType=dailyVolume","publisher":"DefiLlama","source_role":"independent","tier":"B","checked_at":"2026-08-03T19:45:03.000Z","evidence_locator":"total30d and change_1m fields."},{"id":"source:adi:fees","title":"ADI fees API","url":"https://api.llama.fi/overview/fees/ADI?dataType=dailyFees","publisher":"DefiLlama","source_role":"independent","tier":"B","checked_at":"2026-08-03T19:45:03.000Z","evidence_locator":"total30d field."},{"id":"source:adi:revenue","title":"ADI revenue API","url":"https://api.llama.fi/overview/fees/ADI?dataType=dailyRevenue","publisher":"DefiLlama","source_role":"independent","tier":"B","checked_at":"2026-08-03T19:45:03.000Z","evidence_locator":"total30d field."},{"id":"source:adi:stables","title":"Stablecoin supply by chain API","url":"https://stablecoins.llama.fi/stablecoinchains","publisher":"DefiLlama","source_role":"independent","tier":"B","checked_at":"2026-08-03T19:45:03.000Z","evidence_locator":"ADI row and peggedUSD field."}]',
  '{"canonical_profile":{"schema":"chaindump-entity-profile","version":1,"identity":{"id":"blockchain:adi","type":"blockchain","slug":"adi","name":"ADI","aliases":[]},"classification":{"subtype":"Ethereum ZK rollup","tags":["zk_rollup","ethereum","institutional","adi_token"],"chains":["Ethereum"],"jurisdictions":[]},"status":{"operating_state":"operating","as_of":"2026-08-03","claim_ids":["claim:adi:status"]},"outcome":{"label":"middling","as_of":"2026-08-03","rule_id":"blockchain-lifecycle-v1","confidence":"medium","claim_ids":["claim:adi:outcome"]},"analysis":{"sections":{"what_it_is":{"body":"ADI is an Ethereum ZK rollup aimed at governments, banks and regulated institutions. ADI is the gas token. The live network uses ZKsync OS execution and an Airbender prover, while several architecture and institutional-adoption goals are still being built. Partnerships and roadmap language show a distribution strategy; they do not prove that customers are running production workloads.","as_of":"2026-08-03","claim_ids":["claim:adi:section:what_it_is:1","claim:adi:section:what_it_is:2"]},"what_happened":{"body":"ADI launched in December 2025 and quickly accumulated a small but resilient capital base. TVL peaked at $3.99 million on July 23, 2026 and was $3.73 million at review, only 6.31% lower. Thirty-day DEX volume was $120.60 million but had fallen 63.58% from the prior provider comparison. DefiLlama reported $6.13 million of both fees and revenue for the period, a surprising equality that requires provider-method review.","as_of":"2026-08-03","claim_ids":["claim:adi:section:what_happened:1","claim:adi:section:what_happened:2"]},"why_this_outcome":{"body":"ADI has retained most of its small TVL base, which is better than a launch spike followed by immediate collapse. However, the large volume and fee figures sit beside very low activity reported by L2BEAT and a sharp monthly volume decline. That mismatch means we cannot yet say institutional adoption or repeat users caused the result. The fairest call is middling: operating and funded, but not yet proven.","as_of":"2026-08-03","claim_ids":["claim:adi:section:why_this_outcome:1","claim:adi:section:why_this_outcome:2"]},"strategic_choices":{"body":"ADI chose a compliance-first institutional pitch, Ethereum settlement, ZK execution and a separate token for gas and incentives. It also reserved large token allocations for community, treasury and partnerships, released through multi-year schedules. That can finance distribution and development, but it creates continuing unlock pressure. The network prioritized controlled institutional delivery before broad decentralization.","as_of":"2026-08-03","claim_ids":["claim:adi:section:strategic_choices:1","claim:adi:section:strategic_choices:2"]},"operating_model":{"body":"ADI batches transactions through a centralized operator and proves them to Ethereum. L2BEAT classified it Stage 0 at review, with whitelisted proposing, no upgrade delay and multisig-controlled critical actions. L2BEAT also recorded multi-day proof or state-submission gaps in March and April 2026. These are current operating facts; the planned institutional stack and future decentralization are not live safeguards.","as_of":"2026-08-03","claim_ids":["claim:adi:section:operating_model:1","claim:adi:section:operating_model:2"]},"token_and_value_capture":{"body":"ADI pays gas and is described as a future staking and ecosystem asset. Genesis supply was 999,999,999 tokens. Scheduled monthly unlocks began in the first year and several allocations run for six to nine years. We did not publish a market-cap or price claim because the reviewed market pages did not provide a sufficiently consistent circulating-supply picture. Token utility claims are not a substitute for verified fees, users or staking participation.","as_of":"2026-08-03","claim_ids":["claim:adi:section:token_and_value_capture:1","claim:adi:section:token_and_value_capture:2"]},"counterfactual":{"body":"ADI could have used ETH for gas and avoided a new token, reducing unlock and liquidity complexity while giving up a native coordination tool. It could also have delayed the institutional launch until operator controls were broader, trading speed for stronger trust assurances. The practical test is whether the chosen token and controlled rollout produce recurring production workloads rather than partner announcements.","as_of":"2026-08-03","claim_ids":["claim:adi:section:counterfactual:1","claim:adi:section:counterfactual:2"]},"risks_and_unknowns":{"body":"The main risks are centralized upgrades, proving gaps, token unlocks, thin TVL and dependence on a small number of institutional relationships. The exact meaning of provider-reported fees and revenue is unresolved, especially because both values are identical and large relative to TVL. We also lack repeat-user cohorts, independently verified production customers, current token circulation and a complete operator-control map.","as_of":"2026-08-03","claim_ids":["claim:adi:section:risks_and_unknowns:1","claim:adi:section:risks_and_unknowns:2"]},"lifecycle":{"body":"ADI is operating and middling. It retained 93.69% of peak TVL and reports substantial aggregate volume and fees, but monthly volume fell sharply and independent activity remains low. The chain is too new and the metrics are too inconsistent to call it a durable success. The next lifecycle step is proving that named institutions generate repeated transactions and fees without relying on unlocks or centralized intervention.","as_of":"2026-08-03","claim_ids":["claim:adi:section:lifecycle:1","claim:adi:section:lifecycle:2"]},"outlook_and_watch":{"body":"The base case is a small institution-focused rollup whose adoption remains unproven. The outlook improves if reconciled on-chain cohorts show repeat customer use, fee methodology checks out and control broadens. Watch proof submissions, transactions per second, partner deployments, unlocks, TVL, volume and the gap between gross fees and actual operator income. The call worsens if volume keeps falling or roadmap claims continue without public production evidence.","as_of":"2026-08-03","claim_ids":["claim:adi:section:outlook_and_watch:1","claim:adi:section:outlook_and_watch:2"]}}},"metrics":[{"id":"metric:adi:tvl-latest:2026-08-03","dimension":"tvl","label":"TVL","value":3734625,"unit":"usd","currency":"USD","window":{"start":null,"end":"2026-08-03","definition":"latest point"},"as_of":"2026-08-03","method":"Latest historicalChainTvl point.","scope":{"product":"blockchain network","chains":[]},"formula":null,"raw_input_ids":[],"claim_ids":["claim:adi:metric:tvl-latest"],"quality_flags":[]},{"id":"metric:adi:dex-volume-30d:2026-08-03","dimension":"dex_spot_volume","label":"DEX volume (30d)","value":120596987,"unit":"usd","currency":"USD","window":{"start":null,"end":"2026-08-03","definition":"provider-reported rolling 30 days"},"as_of":"2026-08-03","method":"total30d.","scope":{"product":"blockchain network","chains":[]},"formula":null,"raw_input_ids":[],"claim_ids":["claim:adi:metric:dex-volume-30d"],"quality_flags":["not_unique_users"]},{"id":"metric:adi:fees-30d:2026-08-03","dimension":"fees","label":"Fees (30d)","value":6133888,"unit":"usd","currency":"USD","window":{"start":null,"end":"2026-08-03","definition":"provider-reported rolling 30 days"},"as_of":"2026-08-03","method":"total30d.","scope":{"product":"blockchain network","chains":[]},"formula":null,"raw_input_ids":[],"claim_ids":["claim:adi:metric:fees-30d"],"quality_flags":["methodology_requires_review"]},{"id":"metric:adi:revenue-30d:2026-08-03","dimension":"protocol_revenue","label":"Protocol revenue (30d)","value":6133888,"unit":"usd","currency":"USD","window":{"start":null,"end":"2026-08-03","definition":"provider-reported rolling 30 days"},"as_of":"2026-08-03","method":"total30d.","scope":{"product":"blockchain network","chains":[]},"formula":null,"raw_input_ids":[],"claim_ids":["claim:adi:metric:revenue-30d"],"quality_flags":["gr