INSERT INTO chain_analysis (chain, take, sentiment, trend, updated_at, sources, profile)
VALUES (
  'Berachain',
  'Berachain attracted enormous launch capital by paying users to supply liquidity and compete for future rewards. That proved incentives could move money, not that applications had lasting demand. When the launch cycle faded, most capital and trading left. The project then redesigned Proof of Liquidity and deprecated BGT, evidence that the first economic system did not work as intended. The chain remains active, but the retention result is poor.',
  'bearish',
  'Berachain is operating but declining. The chain shipped, BERA remains traded and the economic system was actively redesigned. Yet TVL is 98.59% below peak, monthly volume fell 78.03% and BERA is 98.94% below its high. The current phase is a retention and repair test: can the new BERA/WBERA system support applications without recreating the same incentive-dependent launch spike?',
  '2026-08-03',
  '[{"id":"source:berachain:overview","title":"Berachain documentation","url":"https://docs.berachain.com/","publisher":"Berachain","source_role":"primary","tier":"B","checked_at":"2026-08-03T19:45:03.000Z","evidence_locator":"Current chain and ecosystem overview."},{"id":"source:berachain:pol","title":"Proof of Liquidity overview","url":"https://docs.berachain.com/general/proof-of-liquidity/overview","publisher":"Berachain","source_role":"primary","tier":"B","checked_at":"2026-08-03T19:45:03.000Z","evidence_locator":"Current BERA staking, WBERA emissions, reward vaults and deprecation of the former BGT design."},{"id":"source:berachain:rewards","title":"Proof of Liquidity block rewards","url":"https://docs.berachain.com/general/proof-of-liquidity/block-rewards","publisher":"Berachain","source_role":"primary","tier":"B","checked_at":"2026-08-03T19:45:03.000Z","evidence_locator":"Current top-69 validator rule and per-block WBERA allocations."},{"id":"source:berachain:bgt","title":"BGT token documentation","url":"https://docs.berachain.com/general/tokens/bgt","publisher":"Berachain","source_role":"primary","tier":"B","checked_at":"2026-08-03T19:45:03.000Z","evidence_locator":"Current deprecation and residual-claim treatment for BGT."},{"id":"source:berachain:bex","title":"What is BEX","url":"https://docs.berachain.com/bex/learn/what-is-bex","publisher":"Berachain","source_role":"primary","tier":"B","checked_at":"2026-08-03T19:45:03.000Z","evidence_locator":"BEX application boundary and current disclosed Balancer V2 vulnerability warning."},{"id":"source:berachain:tvl","title":"Berachain historical TVL API","url":"https://api.llama.fi/v2/historicalChainTvl/Berachain","publisher":"DefiLlama","source_role":"independent","tier":"B","checked_at":"2026-08-03T19:45:03.000Z","evidence_locator":"Latest and maximum points in the returned daily TVL series."},{"id":"source:berachain:volume","title":"Berachain DEX volume API","url":"https://api.llama.fi/overview/dexs/Berachain?dataType=dailyVolume","publisher":"DefiLlama","source_role":"independent","tier":"B","checked_at":"2026-08-03T19:45:03.000Z","evidence_locator":"total30d and change_1m fields."},{"id":"source:berachain:fees","title":"Berachain fees API","url":"https://api.llama.fi/overview/fees/Berachain?dataType=dailyFees","publisher":"DefiLlama","source_role":"independent","tier":"B","checked_at":"2026-08-03T19:45:03.000Z","evidence_locator":"total30d field."},{"id":"source:berachain:revenue","title":"Berachain revenue API","url":"https://api.llama.fi/overview/fees/Berachain?dataType=dailyRevenue","publisher":"DefiLlama","source_role":"independent","tier":"B","checked_at":"2026-08-03T19:45:03.000Z","evidence_locator":"total30d field."},{"id":"source:berachain:stables","title":"Stablecoin supply by chain API","url":"https://stablecoins.llama.fi/stablecoinchains","publisher":"DefiLlama","source_role":"independent","tier":"B","checked_at":"2026-08-03T19:45:03.000Z","evidence_locator":"Berachain row and peggedUSD field."},{"id":"source:berachain:market","title":"Berachain token market data","url":"https://api.coingecko.com/api/v3/coins/berachain-bera","publisher":"CoinGecko","source_role":"aggregator","tier":"B","checked_at":"2026-08-03T19:45:03.000Z","evidence_locator":"current price, market cap, FDV and all-time-high fields."}]',
  '{"canonical_profile":{"schema":"chaindump-entity-profile","version":1,"identity":{"id":"blockchain:berachain","type":"blockchain","slug":"berachain","name":"Berachain","aliases":[]},"classification":{"subtype":"EVM L1","tags":["evm","proof_of_liquidity","bera","incentives"],"chains":["Berachain"],"jurisdictions":[]},"status":{"operating_state":"operating","as_of":"2026-08-03","claim_ids":["claim:berachain:status"]},"outcome":{"label":"declining","as_of":"2026-08-03","rule_id":"blockchain-lifecycle-v1","confidence":"high","claim_ids":["claim:berachain:outcome"]},"analysis":{"sections":{"what_it_is":{"body":"Berachain is an EVM-compatible Layer 1 built around Proof of Liquidity. Today validators stake BERA, and WBERA emissions are routed through reward vaults and dedicated streams. The old public story centered on nontransferable BGT for validator direction and governance; current documentation says that model is deprecated. BEX is one application on Berachain, not the chain itself.","as_of":"2026-08-03","claim_ids":["claim:berachain:section:what_it_is:1","claim:berachain:section:what_it_is:2"]},"what_happened":{"body":"Berachain mainnet and BERA launched in February 2025 after a heavily promoted pre-deposit and incentive cycle. TVL reached $3.31 billion in March 2025, then fell to $46.71 million, a 98.59% drawdown. Dollar stablecoins were $59.64 million. Thirty-day DEX volume was $29.89 million, down 78.03% from the prior provider comparison; fees were $111,057.03 and retained revenue was $43,754.57.","as_of":"2026-08-03","claim_ids":["claim:berachain:section:what_happened:1","claim:berachain:section:what_happened:2"]},"why_this_outcome":{"body":"Berachain attracted enormous launch capital by paying users to supply liquidity and compete for future rewards. That proved incentives could move money, not that applications had lasting demand. When the launch cycle faded, most capital and trading left. The project then redesigned Proof of Liquidity and deprecated BGT, evidence that the first economic system did not work as intended. The chain remains active, but the retention result is poor.","as_of":"2026-08-03","claim_ids":["claim:berachain:section:why_this_outcome:1","claim:berachain:section:why_this_outcome:2"]},"strategic_choices":{"body":"Berachain chose an application-aware incentive system instead of ordinary fee-only staking. It used BERA for gas and security, BGT for the original reward-direction model, and first-party applications such as BEX to seed activity. The team later replaced the BGT-centered design with BERA staking, WBERA emissions and an incentive auction. That preserves the liquidity thesis while admitting that the original mechanism needed substantial change.","as_of":"2026-08-03","claim_ids":["claim:berachain:section:strategic_choices:1","claim:berachain:section:strategic_choices:2"]},"operating_model":{"body":"The top 69 validators by staked BERA produce blocks. Each block currently sends WBERA to the operator and to reward vaults, where applications can add incentives. This can coordinate security and liquidity, but it ties validator and application economics to ongoing emissions and auction demand. BEX’s disclosed Balancer V2 vulnerability is an application risk; it should not be described as a consensus failure or counted as separate chain volume.","as_of":"2026-08-03","claim_ids":["claim:berachain:section:operating_model:1","claim:berachain:section:operating_model:2"]},"token_and_value_capture":{"body":"BERA pays gas, secures validators and now anchors Proof of Liquidity. WBERA is the wrapped form used for emissions. BGT remains only as a deprecated residual claim path, not the current governance-and-reward engine. CoinGecko observed BERA at $0.157183, with a $47.47 million market capitalization and $87.15 million fully diluted value, 98.94% below its recorded high. Emissions can create activity while diluting holders if organic fees do not catch up.","as_of":"2026-08-03","claim_ids":["claim:berachain:section:token_and_value_capture:1","claim:berachain:section:token_and_value_capture:2"]},"counterfactual":{"body":"Berachain could have launched with conventional BERA staking and smaller application grants, reducing reflexive complexity but losing its distinctive liquidity pitch. It could also have kept BEX and other first-party apps separate from consensus incentives, making product performance easier to measure. The redesign moves closer to simpler staking, but continued emissions still need to earn durable users.","as_of":"2026-08-03","claim_ids":["claim:berachain:section:counterfactual:1","claim:berachain:section:counterfactual:2"]},"risks_and_unknowns":{"body":"The main risks are incentive dependence, token dilution, validator concentration, application vulnerabilities and another economic redesign. BEX still discloses exposure to a known Balancer V2 issue while planning a future migration. We lack incentive-adjusted volume, repeat-user cohorts, validator beneficial ownership, complete treasury spending and proof that the new auction generates fees greater than its emissions.","as_of":"2026-08-03","claim_ids":["claim:berachain:section:risks_and_unknowns:1","claim:berachain:section:risks_and_unknowns:2"]},"lifecycle":{"body":"Berachain is operating but declining. The chain shipped, BERA remains traded and the economic system was actively redesigned. Yet TVL is 98.59% below peak, monthly volume fell 78.03% and BERA is 98.94% below its high. The current phase is a retention and repair test: can the new BERA/WBERA system support applications without recreating the same incentive-dependent launch spike?","as_of":"2026-08-03","claim_ids":["claim:berachain:section:lifecycle:1","claim:berachain:section:lifecycle:2"]},"outlook_and_watch":{"body":"The base case is a much smaller chain that survives by narrowing incentives and retaining a few core applications. The outlook improves if TVL stabilizes, auction-funded rewards exceed emissions, volume persists and several independent apps generate fees. Watch BEX’s Balancer migration, BERA stake concentration, WBERA issuance, incentive spend, stablecoins, repeat users and governance changes. The call worsens if each new reward program produces only another temporary liquidity spike.","as_of":"2026-08-03","claim_ids":["claim:berachain:section:outlook_and_watch:1","claim:berachain:section:outlook_and_watch:2"]}}},"metrics":[{"id":"metric:berachain:tvl-latest:2026-08-03","dimension":"tvl","label":"TVL","value":46705476,"unit":"usd","currency":"USD","window":{"start":null,"end":"2026-08-03","definition":"latest point"},"as_of":"2026-08-03","method":"Latest historicalChainTvl point.","scope":{"product":"blockchain network","chains":[]},"formula":null,"raw_input_ids":[],"claim_ids":["claim:berachain:metric:tvl-latest"],"quality_flags":[]},{"id":"metric:berachain:stablecoins-latest:2026-08-03","dimension":"stablecoin_supply","label":"Dollar stablecoin supply","value":59638476.05122793,"unit":"usd","currency":"USD","window":{"start":null,"end":"2026-08-03","definition":"latest point"},"as_of":"2026-08-03","method":"peggedUSD field.","scope":{"product":"blockchain network","chains":[]},"formula":null,"raw_input_ids":[],"claim_ids":["claim:berachain:metric:stablecoins-latest"],"quality_flags":[]},{"id":"metric:berachain:dex-volume-30d:2026-08-03","dimension":"dex_spot_volume","label":"DEX volume (30d)","value":29887102.54,"unit":"usd","currency":"USD","window":{"start":null,"end":"2026-08-03","definition":"provider-reported rolling 30 days"},"as_of":"2026-08-03","method":"total30d.","scope":{"product":"blockchain network","chains":[]},"formula":null,"raw_input_ids":[],"claim_ids":["claim:berachain:metric:dex-volume-30d"],"quality_flags":["not_unique_users","incentive_adjustment_unknown"]},{"id":"metric:berachain:fees-30d:2026-08-03","dimension":"fees","label":"Fees (30d)","value":111057.03,"unit":"usd","currency":"USD","window":{"start":null,"end":"2026-08-03","definition":"provider-reported ro