WITH canonical_seed(payload) AS (VALUES ('{"chain":"Katana","sources":[{"id":"source:katana:overview","title":"Katana documentation","url":"https://docs.katana.network/","publisher":"Katana","source_role":"primary","tier":"B","checked_at":"2026-08-03T19:45:03.000Z","evidence_locator":"Current DeFi L2, core applications, Vault Bridge, sequencer-fee and Agglayer design."},{"id":"source:katana:liquidity","title":"Katana chain-owned liquidity","url":"https://docs.katana.network/katana/core-concepts/chain-owned-liquidity/","publisher":"Katana","source_role":"primary","tier":"B","checked_at":"2026-08-03T19:45:03.000Z","evidence_locator":"Current chain-owned-liquidity funding and deployment design."},{"id":"source:katana:risk","title":"Katana risk overview","url":"https://docs.katana.network/katana/core-concepts/risk/","publisher":"Katana","source_role":"primary","tier":"B","checked_at":"2026-08-03T19:45:03.000Z","evidence_locator":"Current smart-contract, bridge, vault and yield dependencies."},{"id":"source:katana:token","title":"KAT token overview","url":"https://docs.katana.network/katana/how-to/kat-token-overview/","publisher":"Katana","source_role":"primary","tier":"B","checked_at":"2026-08-03T19:45:03.000Z","evidence_locator":"Current KAT transferability and vKAT voting and cooldown mechanics."},{"id":"source:katana:tge","title":"Katana TGE is here","url":"https://katana.network/blog/the-wait-is-over-katana-tge-is-here","publisher":"Katana","published_at":"2026-03-18","source_role":"primary","tier":"B","checked_at":"2026-08-03T19:45:03.000Z","evidence_locator":"Dated KAT launch and vKAT Armory activation."},{"id":"source:katana:l2beat","title":"Katana risk analysis","url":"https://l2beat.com/scaling/projects/katana","publisher":"L2BEAT","source_role":"independent","tier":"A","checked_at":"2026-08-03T19:45:03.000Z","evidence_locator":"Current Stage 0, operator, bridge, vault, upgrade and exit-risk panels."},{"id":"source:katana:tvl","title":"Katana historical TVL API","url":"https://api.llama.fi/v2/historicalChainTvl/Katana","publisher":"DefiLlama","source_role":"independent","tier":"B","checked_at":"2026-08-03T19:45:03.000Z","evidence_locator":"Latest and maximum points in the returned daily TVL series."},{"id":"source:katana:volume","title":"Katana DEX volume API","url":"https://api.llama.fi/overview/dexs/Katana?dataType=dailyVolume","publisher":"DefiLlama","source_role":"independent","tier":"B","checked_at":"2026-08-03T19:45:03.000Z","evidence_locator":"total30d and change_1m fields."},{"id":"source:katana:fees","title":"Katana fees API","url":"https://api.llama.fi/overview/fees/Katana?dataType=dailyFees","publisher":"DefiLlama","source_role":"independent","tier":"B","checked_at":"2026-08-03T19:45:03.000Z","evidence_locator":"total30d field."},{"id":"source:katana:revenue","title":"Katana revenue API","url":"https://api.llama.fi/overview/fees/Katana?dataType=dailyRevenue","publisher":"DefiLlama","source_role":"independent","tier":"B","checked_at":"2026-08-03T19:45:03.000Z","evidence_locator":"total30d field."},{"id":"source:katana:stables","title":"Stablecoin supply by chain API","url":"https://stablecoins.llama.fi/stablecoinchains","publisher":"DefiLlama","source_role":"independent","tier":"B","checked_at":"2026-08-03T19:45:03.000Z","evidence_locator":"Katana row and peggedUSD field."},{"id":"source:katana:market","title":"Katana token market data","url":"https://api.coingecko.com/api/v3/coins/katana-network-token","publisher":"CoinGecko","source_role":"aggregator","tier":"B","checked_at":"2026-08-03T19:45:03.000Z","evidence_locator":"current price, market cap, FDV and all-time-high fields."}],"forensic_analysis":{"version":"forensic-analysis-v1","observation_snapshot":{"observed_at":"2026-08-03T19:40:32.300Z","observation_completed_at":"2026-08-03T19:45:03.000Z","provider":"DefiLlama, CoinGecko and L2BEAT","historical_tvl_point_date":"2026-08-03","latest_tvl_usd":64978331,"peak_tvl_usd":711046604,"peak_tvl_date":"2026-03-07","tvl_drawdown_pct":90.86,"stablecoin_supply":{"pegged_usd":18200180.180766344},"dex_volume_30d_usd":24808092,"dex_volume_change_1m_pct":-58.15,"fees_30d_usd":287146.41,"revenue_30d_usd":14255.52,"boundary":"Core-app, Vault Bridge and base-chain economics are not combined."},"outcome":{"label":"declining","summary":"Katana is active but declining after losing 90.86% of peak TVL. Its curated apps, bridge-yield model and KAT launch are live, but they have not yet produced durable capital or volume retention.","confidence":"high","as_of":"2026-08-03","source_refs":["source:katana:tvl","source:katana:volume","source:katana:fees","source:katana:revenue","source:katana:market","source:katana:l2beat"]},"why":{"summary":"Concentrated liquidity and recycled economics created a strong launch, while product, bridge and incentive concentration made demand less durable and harder to separate from the system’s own capital.","confidence":"medium","source_refs":["source:katana:overview","source:katana:liquidity","source:katana:tvl","source:katana:volume","source:katana:market","source:katana:l2beat"]},"strategic_choices":[{"decision":"Concentrate liquidity in a curated DeFi stack.","consequence":"Core markets can deepen while ecosystem and app risk concentrate.","confidence":"high","source_refs":["source:katana:overview","source:katana:liquidity"]},{"decision":"Deploy selected bridge assets into external strategies.","consequence":"The chain can fund yield while adding custody, strategy and accounting risk.","confidence":"high","source_refs":["source:katana:risk","source:katana:l2beat"]},{"decision":"Launch KAT/vKAT while retaining ETH gas.","consequence":"Governance and incentives gain a token without making it the universal control or fee asset.","confidence":"high","source_refs":["source:katana:token","source:katana:tge"]}],"counterfactual":{"summary":"A general-purpose L2 would reduce curation risk; an idle bridge would reduce strategy risk; ETH-only economics would remove token dilution. Each alternative gives up part of Katana’s integrated liquidity design.","confidence":"medium","source_refs":["source:katana:overview","source:katana:liquidity","source:katana:risk","source:katana:token"]},"watch":[{"signal":"TVL, stablecoins, repeat traders, app concentration and incentive-adjusted volume.","implication":"Persistence would show demand beyond chain-owned liquidity.","source_refs":["source:katana:tvl","source:katana:stables","source:katana:volume","source:katana:liquidity"]},{"signal":"Vault Bridge positions, realized yield, losses, sequencer fees and KAT/vKAT participation.","implication":"Transparent positive net economics would strengthen the model.","source_refs":["source:katana:risk","source:katana:overview","source:katana:token"]}],"unknowns":[{"question":"How much volume and TVL persist without incentives?","resolution_trigger":"A two-quarter incentive-adjusted cohort and flow analysis."},{"question":"Where are all Vault Bridge assets and who controls them?","resolution_trigger":"A reconciled position, custody and control statement."},{"question":"Which apps generate chain fees and retained users?","resolution_trigger":"Non-overlapping app-level fee and cohort data."},{"question":"Who beneficially controls upgrades and emergency actions?","resolution_trigger":"An independent entity-level control map."}],"review":{"status":"current","last_reviewed_at":"2026-08-03","next_review_at":"2026-08-10","reviewer":"chaindump-research-desk"}}}'))
UPDATE chain_facts AS facts
SET
  data = json_set(
    facts.data,
    '$.forensic_analysis', json(json_extract((SELECT payload FROM canonical_seed), '$.forensic_analysis')),
    '$.canonical_profile_ref', 'chain_analysis.profile.canonical_profile'
  ),
  sources = (SELECT json_group_array(json(source_json))
      FROM (
        SELECT source_json
        FROM (
          SELECT
            CASE
              WHEN new_source.value IS NULL THEN old_source.value
              ELSE json_patch(old_source.value, new_source.value)
            END AS source_json,
            old_source.key AS position
          FROM json_each(COALESCE(facts.sources, '[]')) AS old_source
          LEFT JOIN json_each(COALESCE(json_extract((SELECT payload FROM canonical_seed), '$.sources'), '[]')) AS new_source
            ON json_extract(new_source.value, '$.url') = json_extract(old_source.value, '$.url')
          WHERE json_extract(old_source.value, '$.url') IS NULL
             OR old_source.key = (
               SELECT MIN(candidate.key)
               FROM json_each(COALESCE(facts.sources, '[]')) AS candidate
               WHERE json_extract(candidate.value, '$.url') = json_extract(old_source.value, '$.url')
             )
          UNION ALL
          SELECT new_source.value AS source_json, 10000 + new_source.key AS position
          FROM json_each(COALESCE(json_extract((SELECT payload FROM canonical_seed), '$.sources'), '[]')) AS new_source
          WHERE NOT EXISTS (
            SELECT 1 FROM json_each(COALESCE(facts.sources, '[]')) AS existing
            WHERE json_extract(existing.value, '$.url') = json_extract(new_source.value, '$.url')
          )
        )
        ORDER BY position
      )),
  updated_at = '2026-08-03'
WHERE facts.chain = json_extract((SELECT payload FROM canonical_seed), '$.chain')
  AND facts.dimension = 'synthesis';
-- canonical-synthesis-end Katana

