-- canonical-profile-start Katana
INSERT INTO chain_analysis (chain, take, sentiment, trend, updated_at, sources, profile)
VALUES (
  'Katana',
  'Katana’s launch concentrated liquidity and routed sequencer and bridge economics back into the ecosystem. That produced a large initial capital base, but most of it did not stay. The narrow app set can improve depth, yet it also concentrates product risk and makes incentives difficult to separate from demand. A live token and perps product did not reverse the capital or monthly volume decline by review.',
  'bearish',
  'Katana is operating but declining. It shipped the rollup, core DeFi apps, KAT/vKAT and new trading products. However, TVL is 90.86% below peak, monthly volume fell 58.15% and KAT is 85.27% below its high. The next test is whether the integrated financial stack retains capital and traders after launch incentives, rather than whether another product can create a short burst.',
  '2026-08-03',
  '[{"id":"source:katana:overview","title":"Katana documentation","url":"https://docs.katana.network/","publisher":"Katana","source_role":"primary","tier":"B","checked_at":"2026-08-03T19:45:03.000Z","evidence_locator":"Current DeFi L2, core applications, Vault Bridge, sequencer-fee and Agglayer design."},{"id":"source:katana:liquidity","title":"Katana chain-owned liquidity","url":"https://docs.katana.network/katana/core-concepts/chain-owned-liquidity/","publisher":"Katana","source_role":"primary","tier":"B","checked_at":"2026-08-03T19:45:03.000Z","evidence_locator":"Current chain-owned-liquidity funding and deployment design."},{"id":"source:katana:risk","title":"Katana risk overview","url":"https://docs.katana.network/katana/core-concepts/risk/","publisher":"Katana","source_role":"primary","tier":"B","checked_at":"2026-08-03T19:45:03.000Z","evidence_locator":"Current smart-contract, bridge, vault and yield dependencies."},{"id":"source:katana:token","title":"KAT token overview","url":"https://docs.katana.network/katana/how-to/kat-token-overview/","publisher":"Katana","source_role":"primary","tier":"B","checked_at":"2026-08-03T19:45:03.000Z","evidence_locator":"Current KAT transferability and vKAT voting and cooldown mechanics."},{"id":"source:katana:tge","title":"Katana TGE is here","url":"https://katana.network/blog/the-wait-is-over-katana-tge-is-here","publisher":"Katana","published_at":"2026-03-18","source_role":"primary","tier":"B","checked_at":"2026-08-03T19:45:03.000Z","evidence_locator":"Dated KAT launch and vKAT Armory activation."},{"id":"source:katana:l2beat","title":"Katana risk analysis","url":"https://l2beat.com/scaling/projects/katana","publisher":"L2BEAT","source_role":"independent","tier":"A","checked_at":"2026-08-03T19:45:03.000Z","evidence_locator":"Current Stage 0, operator, bridge, vault, upgrade and exit-risk panels."},{"id":"source:katana:tvl","title":"Katana historical TVL API","url":"https://api.llama.fi/v2/historicalChainTvl/Katana","publisher":"DefiLlama","source_role":"independent","tier":"B","checked_at":"2026-08-03T19:45:03.000Z","evidence_locator":"Latest and maximum points in the returned daily TVL series."},{"id":"source:katana:volume","title":"Katana DEX volume API","url":"https://api.llama.fi/overview/dexs/Katana?dataType=dailyVolume","publisher":"DefiLlama","source_role":"independent","tier":"B","checked_at":"2026-08-03T19:45:03.000Z","evidence_locator":"total30d and change_1m fields."},{"id":"source:katana:fees","title":"Katana fees API","url":"https://api.llama.fi/overview/fees/Katana?dataType=dailyFees","publisher":"DefiLlama","source_role":"independent","tier":"B","checked_at":"2026-08-03T19:45:03.000Z","evidence_locator":"total30d field."},{"id":"source:katana:revenue","title":"Katana revenue API","url":"https://api.llama.fi/overview/fees/Katana?dataType=dailyRevenue","publisher":"DefiLlama","source_role":"independent","tier":"B","checked_at":"2026-08-03T19:45:03.000Z","evidence_locator":"total30d field."},{"id":"source:katana:stables","title":"Stablecoin supply by chain API","url":"https://stablecoins.llama.fi/stablecoinchains","publisher":"DefiLlama","source_role":"independent","tier":"B","checked_at":"2026-08-03T19:45:03.000Z","evidence_locator":"Katana row and peggedUSD field."},{"id":"source:katana:market","title":"Katana token market data","url":"https://api.coingecko.com/api/v3/coins/katana-network-token","publisher":"CoinGecko","source_role":"aggregator","tier":"B","checked_at":"2026-08-03T19:45:03.000Z","evidence_locator":"current price, market cap, FDV and all-time-high fields."}]',
  '{"canonical_profile":{"schema":"chaindump-entity-profile","version":1,"identity":{"id":"blockchain:katana","type":"blockchain","slug":"katana","name":"Katana","aliases":[]},"classification":{"subtype":"Ethereum optimistic rollup","tags":["defi_l2","op_stack","kat","chain_owned_liquidity"],"chains":["Ethereum"],"jurisdictions":[]},"status":{"operating_state":"operating","as_of":"2026-08-03","claim_ids":["claim:katana:status"]},"outcome":{"label":"declining","as_of":"2026-08-03","rule_id":"blockchain-lifecycle-v1","confidence":"high","claim_ids":["claim:katana:outcome"]},"analysis":{"sections":{"what_it_is":{"body":"Katana is an Ethereum Layer 2 designed around a small set of DeFi applications and chain-owned liquidity. It uses ETH for gas. KAT is a separate governance and incentive token; locking KAT creates nontransferable vKAT. Morpho, Sushi, the Vault Bridge and Katana Perps are products or financial layers on the chain, not the chain itself, so their balances and revenues must not be silently combined.","as_of":"2026-08-03","claim_ids":["claim:katana:section:what_it_is:1","claim:katana:section:what_it_is:2"]},"what_happened":{"body":"Katana launched in July 2025, accumulated $711.05 million of TVL by March 2026 and launched KAT on March 18. TVL then fell to $64.98 million, a 90.86% drawdown. Dollar stablecoins were $18.20 million. Thirty-day DEX volume was $24.81 million, down 58.15% from the prior provider comparison; fees were $287,146.41 and provider-reported retained revenue was $14,255.52.","as_of":"2026-08-03","claim_ids":["claim:katana:section:what_happened:1","claim:katana:section:what_happened:2"]},"why_this_outcome":{"body":"Katana’s launch concentrated liquidity and routed sequencer and bridge economics back into the ecosystem. That produced a large initial capital base, but most of it did not stay. The narrow app set can improve depth, yet it also concentrates product risk and makes incentives difficult to separate from demand. A live token and perps product did not reverse the capital or monthly volume decline by review.","as_of":"2026-08-03","claim_ids":["claim:katana:section:why_this_outcome:1","claim:katana:section:why_this_outcome:2"]},"strategic_choices":{"body":"Katana chose a curated DeFi stack, chain-owned liquidity, a Vault Bridge that deploys selected assets into Ethereum strategies, and a token that does not pay gas. It routes net sequencer fees into liquidity rather than treating them only as operator income. KAT holders can lock into vKAT for voting with a 60-day withdrawal delay. These choices aim to deepen a few markets, while adding bridge, strategy, governance and concentration risk.","as_of":"2026-08-03","claim_ids":["claim:katana:section:strategic_choices:1","claim:katana:section:strategic_choices:2"]},"operating_model":{"body":"Katana batches transactions through an operator-controlled OP Stack rollup and uses ZK proofs through OP Succinct and the Agglayer design. L2BEAT classified it Stage 0 with no user exit window before upgrades. Vault Bridge assets can be deployed away from Katana into external strategies, while users hold bridge representations on Katana. Those yield flows and app fees are distinct from base-chain sequencer revenue.","as_of":"2026-08-03","claim_ids":["claim:katana:section:operating_model:1","claim:katana:section:operating_model:2"]},"token_and_value_capture":{"body":"ETH pays gas. KAT provides governance and incentives, and vKAT is the nontransferable locked form. KAT does not govern every chain upgrade or the Vault Bridge, so token voting should not be described as complete system control. CoinGecko observed KAT at $0.00434103, with a $13.36 million market capitalization and $43.41 million fully diluted value, 85.27% below its recorded high.","as_of":"2026-08-03","claim_ids":["claim:katana:section:token_and_value_capture:1","claim:katana:section:token_and_value_capture:2"]},"counterfactual":{"body":"Katana could have launched as a general-purpose L2 and let independent apps compete for liquidity, reducing curation risk while losing its focused market structure. It could have kept assets on Katana instead of deploying them through the Vault Bridge, simplifying custody but giving up external yield. An ETH-only model would avoid token dilution but remove vKAT governance and incentives.","as_of":"2026-08-03","claim_ids":["claim:katana:section:counterfactual:1","claim:katana:section:counterfactual:2"]},"risks_and_unknowns":{"body":"The main risks are Stage 0 control, bridge and strategy losses, core-app concentration, token dilution and incentive dependence. Chain-owned liquidity may support markets while hiding weak third-party demand. We lack repeat-user cohorts, app-by-app fee attribution, a complete Vault Bridge asset and yield reconciliation, beneficial ownership of upgrade controls and a net income statement after incentives and strategy costs.","as_of":"2026-08-03","claim_ids":["claim:katana:section:risks_and_unknowns:1","claim:katana:section:risks_and_unknowns:2"]},"lifecycle":{"body":"Katana is operating but declining. It shipped the rollup, core DeFi apps, KAT/vKAT and new trading products. However, TVL is 90.86% below peak, monthly volume fell 58.15% and KAT is 85.27% below its high. The next test is whether the integrated financial stack retains capital and traders after launch incentives, rather than whether another product can create a short burst.","as_of":"2026-08-03","claim_ids":["claim:katana:section:lifecycle:1","claim:katana:section:lifecycle:2"]},"outlook_and_watch":{"body":"The base case is a smaller curated DeFi chain whose economics depend on a few apps and bridge strategies. The call improves if TVL stabilizes, independent apps and users grow, fee retention rises and control matures. Watch Vault Bridge positions and losses, sequencer-fee recycling, app concentration, vKAT participation, KAT unlocks, repeat traders and the difference between bridge yield and user yield. The call worsens if capital keeps lea