WITH canonical_seed(payload) AS (VALUES ('{"chain":"Rootstock","sources":[{"id":"source:rootstock:overview","title":"Rootstock developer portal","url":"https://dev.rootstock.io/","publisher":"Rootstock","source_role":"primary","tier":"B","checked_at":"2026-08-03T19:45:03.000Z","evidence_locator":"Current EVM sidechain, merge-mining, rBTC and PowPeg descriptions."},{"id":"source:rootstock:federation","title":"PowPeg federation trust discussion","url":"https://research.rsk.dev/t/federation-trust/315","publisher":"Rootstock Research","source_role":"primary","tier":"B","checked_at":"2026-08-03T19:45:03.000Z","evidence_locator":"Operator research discussion of the federation label and inability to prove private keys were not copied."},{"id":"source:rootstock:rskip383","title":"RSKIP-383 PowPeg composition changes","url":"https://ips.rootstock.io/IPs/RSKIP383.html","publisher":"Rootstock","source_role":"primary","tier":"B","checked_at":"2026-08-03T19:45:03.000Z","evidence_locator":"Adopted PowPeg composition-change process."},{"id":"source:rootstock:rskip419","title":"RSKIP-419 PowPeg spendability validation","url":"https://ips.rootstock.io/IPs/RSKIP419.html","publisher":"Rootstock","source_role":"primary","tier":"B","checked_at":"2026-08-03T19:45:03.000Z","evidence_locator":"Adopted validation change for PowPeg spendability."},{"id":"source:rootstock:union","title":"Union: a trust-minimized bridge for Rootstock","url":"https://arxiv.org/abs/2501.07435","publisher":"Rootstock Research","source_role":"primary","tier":"B","checked_at":"2026-08-03T19:45:03.000Z","evidence_locator":"Research design for a future BitVMX-based bridge; not evidence of production deployment."},{"id":"source:rootstock:spark","title":"Rootstock EVM sidechain analysis","url":"https://www.spark.money/research/rootstock-rsk-evm-bitcoin-analysis","publisher":"Spark","source_role":"independent","tier":"B","checked_at":"2026-08-03T19:45:03.000Z","evidence_locator":"Independent current analysis of the PowPeg threshold and Union testnet/roadmap boundary."},{"id":"source:rootstock:tvl","title":"Rootstock historical TVL API","url":"https://api.llama.fi/v2/historicalChainTvl/Rootstock","publisher":"DefiLlama","source_role":"independent","tier":"B","checked_at":"2026-08-03T19:45:03.000Z","evidence_locator":"Latest and maximum points in the returned daily TVL series."},{"id":"source:rootstock:volume","title":"Rootstock DEX volume API","url":"https://api.llama.fi/overview/dexs/Rootstock?dataType=dailyVolume","publisher":"DefiLlama","source_role":"independent","tier":"B","checked_at":"2026-08-03T19:45:03.000Z","evidence_locator":"total30d and change_1m fields."},{"id":"source:rootstock:fees","title":"Rootstock fees API","url":"https://api.llama.fi/overview/fees/Rootstock?dataType=dailyFees","publisher":"DefiLlama","source_role":"independent","tier":"B","checked_at":"2026-08-03T19:45:03.000Z","evidence_locator":"total30d field."},{"id":"source:rootstock:revenue","title":"Rootstock revenue API","url":"https://api.llama.fi/overview/fees/Rootstock?dataType=dailyRevenue","publisher":"DefiLlama","source_role":"independent","tier":"B","checked_at":"2026-08-03T19:45:03.000Z","evidence_locator":"total30d field."},{"id":"source:rootstock:stables","title":"Stablecoin supply by chain API","url":"https://stablecoins.llama.fi/stablecoinchains","publisher":"DefiLlama","source_role":"independent","tier":"B","checked_at":"2026-08-03T19:45:03.000Z","evidence_locator":"Rootstock row and peggedUSD field."}],"forensic_analysis":{"version":"forensic-analysis-v1","observation_snapshot":{"observed_at":"2026-08-03T19:40:32.300Z","observation_completed_at":"2026-08-03T19:45:03.000Z","provider":"DefiLlama, Rootstock Research and Spark","historical_tvl_point_date":"2026-08-03","latest_tvl_usd":71082992,"peak_tvl_usd":283447916,"peak_tvl_date":"2025-10-07","tvl_drawdown_pct":74.92,"stablecoin_supply":{"pegged_usd":11909690.768024461},"dex_volume_30d_usd":44050794,"dex_volume_change_1m_pct":-36.55,"fees_30d_usd":115313,"revenue_30d_usd":1,"security_boundary":"Merge-mined block ordering does not remove current PowPeg federation or unilateral-exit assumptions."},"outcome":{"label":"declining","summary":"Rootstock remains a working Bitcoin sidechain, but TVL is 74.92% below peak, monthly volume is falling and current revenue is negligible. Its mature niche is declining, not dead.","confidence":"high","as_of":"2026-08-03","source_refs":["source:rootstock:tvl","source:rootstock:volume","source:rootstock:fees","source:rootstock:revenue","source:rootstock:spark"]},"why":{"summary":"EVM compatibility and rBTC created durable Bitcoin DeFi utility, while PowPeg trust, liquidity friction and newer competitors limited growth. Merge mining does not solve peg custody.","confidence":"medium","source_refs":["source:rootstock:overview","source:rootstock:federation","source:rootstock:spark","source:rootstock:tvl","source:rootstock:volume","source:rootstock:revenue"]},"strategic_choices":[{"decision":"Use Bitcoin merge mining instead of a new validator token.","consequence":"Rootstock aligns block security with miners while relying on their participation and concentration.","confidence":"high","source_refs":["source:rootstock:overview","source:rootstock:spark"]},{"decision":"Use rBTC and a threshold PowPeg.","consequence":"BTC liquidity reaches EVM apps while users accept federation and exit assumptions.","confidence":"high","source_refs":["source:rootstock:federation","source:rootstock:spark"]},{"decision":"Research Union as a future bridge.","consequence":"Trust could fall after production deployment, but current users still rely on PowPeg.","confidence":"high","source_refs":["source:rootstock:union","source:rootstock:spark"]}],"counterfactual":{"summary":"A separate token could fund validators but weaken Bitcoin alignment. A simple custodian could speed bridging but increase trust. A live trust-minimized bridge would help, but Union must not be counted before production.","confidence":"medium","source_refs":["source:rootstock:overview","source:rootstock:union","source:rootstock:spark"]},"watch":[{"signal":"TVL, rBTC supply, repeat users, DEX volume, fees and retained revenue.","implication":"Stability would show the Bitcoin DeFi niche is holding.","source_refs":["source:rootstock:tvl","source:rootstock:stables","source:rootstock:volume","source:rootstock:fees","source:rootstock:revenue"]},{"signal":"PowPeg ownership, signer availability, miner concentration and Union production status.","implication":"Broader controls and a safer exit would improve the security case.","source_refs":["source:rootstock:federation","source:rootstock:rskip383","source:rootstock:rskip419","source:rootstock:union"]}],"unknowns":[{"question":"Who beneficially controls current PowPeg functionaries?","resolution_trigger":"An independently verified ownership and jurisdiction map."},{"question":"Can a user exit without the PowPeg threshold?","resolution_trigger":"A current executable unilateral-exit proof or explicit limitation."},{"question":"Which apps and users generate current fees?","resolution_trigger":"Non-overlapping app-level fee and cohort data."},{"question":"Why did the provider report only $1 of retained revenue?","resolution_trigger":"A provider methodology and operator-income reconciliation."}],"review":{"status":"current","last_reviewed_at":"2026-08-03","next_review_at":"2026-08-10","reviewer":"chaindump-research-desk"}}}'))
UPDATE chain_facts AS facts
SET
  data = json_set(
    facts.data,
    '$.forensic_analysis', json(json_extract((SELECT payload FROM canonical_seed), '$.forensic_analysis')),
    '$.canonical_profile_ref', 'chain_analysis.profile.canonical_profile'
  ),
  sources = (SELECT json_group_array(json(source_json))
      FROM (
        SELECT source_json
        FROM (
          SELECT
            CASE
              WHEN new_source.value IS NULL THEN old_source.value
              ELSE json_patch(old_source.value, new_source.value)
            END AS source_json,
            old_source.key AS position
          FROM json_each(COALESCE(facts.sources, '[]')) AS old_source
          LEFT JOIN json_each(COALESCE(json_extract((SELECT payload FROM canonical_seed), '$.sources'), '[]')) AS new_source
            ON json_extract(new_source.value, '$.url') = json_extract(old_source.value, '$.url')
          WHERE json_extract(old_source.value, '$.url') IS NULL
             OR old_source.key = (
               SELECT MIN(candidate.key)
               FROM json_each(COALESCE(facts.sources, '[]')) AS candidate
               WHERE json_extract(candidate.value, '$.url') = json_extract(old_source.value, '$.url')
             )
          UNION ALL
          SELECT new_source.value AS source_json, 10000 + new_source.key AS position
          FROM json_each(COALESCE(json_extract((SELECT payload FROM canonical_seed), '$.sources'), '[]')) AS new_source
          WHERE NOT EXISTS (
            SELECT 1 FROM json_each(COALESCE(facts.sources, '[]')) AS existing
            WHERE json_extract(existing.value, '$.url') = json_extract(new_source.value, '$.url')
          )
        )
        ORDER BY position
      )),
  updated_at = '2026-08-03'
WHERE facts.chain = json_extract((SELECT payload FROM canonical_seed), '$.chain')
  AND facts.dimension = 'synthesis';
-- canonical-synthesis-end Rootstock

