INSERT INTO chain_analysis (chain, take, sentiment, trend, updated_at, sources, profile)
VALUES (
  'Rootstock',
  'Rootstock solved a durable problem: EVM applications can use a bitcoin-pegged asset without moving all activity to a non-Bitcoin ecosystem. Merge mining reduced the need for a new validator token. But the PowPeg adds signer trust and liquidity friction, while faster L2s and other Bitcoin DeFi systems compete for developers and capital. The chain remains useful, yet current capital, volume and revenue indicate a mature network in decline rather than renewed growth.',
  'bearish',
  'Rootstock is operating but declining. It remains one of the longest-running EVM environments tied to Bitcoin, with meaningful TVL and DEX volume. Still, TVL is 74.92% below peak, monthly volume fell 36.55% and reported retained revenue is negligible. The next lifecycle test is whether better bridge technology and applications can restore demand without overstating Bitcoin’s protection of the current peg.',
  '2026-08-03',
  '[{"id":"source:rootstock:overview","title":"Rootstock developer portal","url":"https://dev.rootstock.io/","publisher":"Rootstock","source_role":"primary","tier":"B","checked_at":"2026-08-03T19:45:03.000Z","evidence_locator":"Current EVM sidechain, merge-mining, rBTC and PowPeg descriptions."},{"id":"source:rootstock:federation","title":"PowPeg federation trust discussion","url":"https://research.rsk.dev/t/federation-trust/315","publisher":"Rootstock Research","source_role":"primary","tier":"B","checked_at":"2026-08-03T19:45:03.000Z","evidence_locator":"Operator research discussion of the federation label and inability to prove private keys were not copied."},{"id":"source:rootstock:rskip383","title":"RSKIP-383 PowPeg composition changes","url":"https://ips.rootstock.io/IPs/RSKIP383.html","publisher":"Rootstock","source_role":"primary","tier":"B","checked_at":"2026-08-03T19:45:03.000Z","evidence_locator":"Adopted PowPeg composition-change process."},{"id":"source:rootstock:rskip419","title":"RSKIP-419 PowPeg spendability validation","url":"https://ips.rootstock.io/IPs/RSKIP419.html","publisher":"Rootstock","source_role":"primary","tier":"B","checked_at":"2026-08-03T19:45:03.000Z","evidence_locator":"Adopted validation change for PowPeg spendability."},{"id":"source:rootstock:union","title":"Union: a trust-minimized bridge for Rootstock","url":"https://arxiv.org/abs/2501.07435","publisher":"Rootstock Research","source_role":"primary","tier":"B","checked_at":"2026-08-03T19:45:03.000Z","evidence_locator":"Research design for a future BitVMX-based bridge; not evidence of production deployment."},{"id":"source:rootstock:spark","title":"Rootstock EVM sidechain analysis","url":"https://www.spark.money/research/rootstock-rsk-evm-bitcoin-analysis","publisher":"Spark","source_role":"independent","tier":"B","checked_at":"2026-08-03T19:45:03.000Z","evidence_locator":"Independent current analysis of the PowPeg threshold and Union testnet/roadmap boundary."},{"id":"source:rootstock:tvl","title":"Rootstock historical TVL API","url":"https://api.llama.fi/v2/historicalChainTvl/Rootstock","publisher":"DefiLlama","source_role":"independent","tier":"B","checked_at":"2026-08-03T19:45:03.000Z","evidence_locator":"Latest and maximum points in the returned daily TVL series."},{"id":"source:rootstock:volume","title":"Rootstock DEX volume API","url":"https://api.llama.fi/overview/dexs/Rootstock?dataType=dailyVolume","publisher":"DefiLlama","source_role":"independent","tier":"B","checked_at":"2026-08-03T19:45:03.000Z","evidence_locator":"total30d and change_1m fields."},{"id":"source:rootstock:fees","title":"Rootstock fees API","url":"https://api.llama.fi/overview/fees/Rootstock?dataType=dailyFees","publisher":"DefiLlama","source_role":"independent","tier":"B","checked_at":"2026-08-03T19:45:03.000Z","evidence_locator":"total30d field."},{"id":"source:rootstock:revenue","title":"Rootstock revenue API","url":"https://api.llama.fi/overview/fees/Rootstock?dataType=dailyRevenue","publisher":"DefiLlama","source_role":"independent","tier":"B","checked_at":"2026-08-03T19:45:03.000Z","evidence_locator":"total30d field."},{"id":"source:rootstock:stables","title":"Stablecoin supply by chain API","url":"https://stablecoins.llama.fi/stablecoinchains","publisher":"DefiLlama","source_role":"independent","tier":"B","checked_at":"2026-08-03T19:45:03.000Z","evidence_locator":"Rootstock row and peggedUSD field."}]',
  '{"canonical_profile":{"schema":"chaindump-entity-profile","version":1,"identity":{"id":"blockchain:rootstock","type":"blockchain","slug":"rootstock","name":"Rootstock","aliases":[]},"classification":{"subtype":"Bitcoin merge-mined sidechain","tags":["bitcoin","evm","merge_mining","federated_peg"],"chains":["Bitcoin","Rootstock"],"jurisdictions":[]},"status":{"operating_state":"operating","as_of":"2026-08-03","claim_ids":["claim:rootstock:status"]},"outcome":{"label":"declining","as_of":"2026-08-03","rule_id":"blockchain-lifecycle-v1","confidence":"high","claim_ids":["claim:rootstock:outcome"]},"analysis":{"sections":{"what_it_is":{"body":"Rootstock is an EVM-compatible Bitcoin sidechain. Bitcoin miners can merge-mine Rootstock blocks, and rBTC is the bitcoin-pegged gas asset. Moving BTC into and out of rBTC depends on the PowPeg federation and hardware-controlled keys. That bridge trust is separate from the hash power used to order Rootstock blocks, so “secured by Bitcoin” does not mean users can always exit without signers.","as_of":"2026-08-03","claim_ids":["claim:rootstock:section:what_it_is:1","claim:rootstock:section:what_it_is:2"]},"what_happened":{"body":"Rootstock has operated for years and built a real Bitcoin DeFi niche. In the reviewed series, TVL peaked at $283.45 million in October 2025 and fell to $71.08 million, a 74.92% drawdown. Dollar stablecoins were $11.91 million. Thirty-day DEX volume was $44.05 million, down 36.55% from the prior provider comparison; fees were $115,313 and provider-reported retained revenue was only $1.","as_of":"2026-08-03","claim_ids":["claim:rootstock:section:what_happened:1","claim:rootstock:section:what_happened:2"]},"why_this_outcome":{"body":"Rootstock solved a durable problem: EVM applications can use a bitcoin-pegged asset without moving all activity to a non-Bitcoin ecosystem. Merge mining reduced the need for a new validator token. But the PowPeg adds signer trust and liquidity friction, while faster L2s and other Bitcoin DeFi systems compete for developers and capital. The chain remains useful, yet current capital, volume and revenue indicate a mature network in decline rather than renewed growth.","as_of":"2026-08-03","claim_ids":["claim:rootstock:section:why_this_outcome:1","claim:rootstock:section:why_this_outcome:2"]},"strategic_choices":{"body":"Rootstock chose merge mining instead of a separate proof-of-stake token, rBTC instead of a floating gas token, and a threshold PowPeg instead of a fully custodial exchange bridge. It adopted changes to federation composition and spendability checks over time. Researchers are developing Union, a BitVMX-based bridge intended to reduce trust, but the reviewed evidence describes research or testnet work, not a production replacement for PowPeg.","as_of":"2026-08-03","claim_ids":["claim:rootstock:section:strategic_choices:1","claim:rootstock:section:strategic_choices:2"]},"operating_model":{"body":"Bitcoin miners merge-mine Rootstock blocks, while EVM nodes execute smart contracts. BTC enters and exits through PowPeg, whose current threshold is described independently as five of nine functionaries. Rootstock improvements can change signer composition and validation, but users still cannot unilaterally recover BTC if the threshold is unavailable. Consensus liveness, contract safety and peg custody are three different risk surfaces.","as_of":"2026-08-03","claim_ids":["claim:rootstock:section:operating_model:1","claim:rootstock:section:operating_model:2"]},"token_and_value_capture":{"body":"rBTC is bitcoin-pegged gas, not a new speculative supply schedule. RIF is an ecosystem token for services and should not be presented as Rootstock’s gas or consensus-security token. That keeps network economics tied to BTC but leaves limited base-layer token value capture. The $1 provider-reported 30-day revenue field needs methodology review and is not proof that every application or miner earned only one dollar.","as_of":"2026-08-03","claim_ids":["claim:rootstock:section:token_and_value_capture:1","claim:rootstock:section:token_and_value_capture:2"]},"counterfactual":{"body":"Rootstock could have used a separate validator token, gaining direct security incentives while losing Bitcoin-miner alignment. It could have used a simpler custodian for BTC, improving speed at the cost of even more explicit trust. A production trust-minimized bridge could reduce PowPeg dependence, but calling Union live before deployment would hide today’s actual exit assumptions.","as_of":"2026-08-03","claim_ids":["claim:rootstock:section:counterfactual:1","claim:rootstock:section:counterfactual:2"]},"risks_and_unknowns":{"body":"The main risks are PowPeg signer availability or collusion, smart-contract losses, weak liquidity, miner concentration and competition from newer Bitcoin systems. Merge-mining percentages do not reveal who controls bridge keys. We lack a current independent functionary ownership map, a complete unilateral-exit analysis, app-level fee concentration, repeat-user cohorts and a provider explanation for the $1 revenue observation.","as_of":"2026-08-03","claim_ids":["claim:rootstock:section:risks_and_unknowns:1","claim:rootstock:section:risks_and_unknowns:2"]},"lifecycle":{"body":"Rootstock is operating but declining. It remains one of the longest-running EVM environments tied to Bitcoin, with meaningful TVL and DEX volume. Still, TVL is 74.92% below peak, monthly volume fell 36.55% and reported retained revenue is negligible. The next lifecycle test is whether better bridge technology and applications can restore demand without overstating Bitcoin’s protection of the current peg.","as_of":"2026-08-03","claim_ids":["claim:rootstock:section:lifecycle:1","claim:rootstock:section:lifecycle:2"]},"outlook_and_watch":{"body":"The base case is continued niche use with gradual decline unless a new application or safer bridge materially changes distribution. The outlook improves if TVL and repeat users stabilize, fees translate into retained revenue and a production bridge reduces unilateral-exit risk. Watch PowPeg membership, HSM procedures, miner concentration, Union deployment status, rBTC supply, bridge delays, app concentration and fee methodology. The call worsens if current bridge trust is marketed as native Bitcoin security.","as_of":"2026-08-03","claim_ids":["claim:rootstock:section:outlook_and_watch:1","claim:rootstock:section:outlook_and_watch:2"]}}},"metrics":[{"id":"metric:rootstock:tvl-latest:2026-08-03","dimension":"tvl","label":"TVL","value":71082992,"unit":"usd","currency":"USD","window":{"start":null,"end":"2026-08-03","definition":"latest point"},"as_of":"2026-08-03","method":"Latest historicalChainTvl point.","scope":{"product":"blockchain network","chains":[]},"formula":null,"raw_input_ids":[],"claim_ids":["claim:rootstock:metric:tvl-latest"],"quality_flags":[]},{"id":"metric:rootstock:stablecoins-latest:2026-08-03","dimension":"stablecoin_supply","label":"Dollar stablecoin supply","value":11909690.768024461,"unit":"usd","currency":"USD","window":{"start":null,"end":"2026-08-03","definition":"latest point"},"as_of":"2026-08-03","method":"peggedUSD field.","scope":{"product":"blockchain network","chains":[]},"formula":null,"raw_input_ids":[],"claim_ids":["claim:rootstock:metric:stablecoins-latest"],"quality_flags":[]},{"id":"metric:rootstock:dex-volume-30d:2026-08-03","dimension":"dex_spot_volume","label":"DEX volume (30d)","value":44050794,"unit":"usd","currency":"USD","window":{"start":null,"end":"2026-08-03","definition":"provider-reported rolling 30 days"},"as_of":"2026-08-03","method":"total30d.","scope":{"product":"blockchain network","chains":[]},"formula":null,"raw_input_ids":[],"claim_ids":["claim:rootstock:metric:dex-volume-30d"],"quality_flags":["not_unique_users"]},{"id":"metric:rootstock:fees-30d:2026-08-03","dimension":"fees","label":"Fees (30d)","value":115313,"unit":"usd","currency":"USD","window":{"start":null,"end":"2026-08-03","definition":"provider-reported rolling 30 days"},"as_of":"2026-08-03","method":"total30d.","scope":{"product":"blockchain network","chains":[]},"formula":null,"raw_input_ids":[],"claim_ids":["claim:rootstock:metric:fees-30d"],"quality_flags":[]},{"id":"metric:rootstock:revenue-30d:2026-08-03","dimension":"protocol_revenue","label":"Protocol revenue (30d)","value":1,"unit":"usd","currency":"USD","window":{"start":null,"end":"2026-08-03","definition":"provider-reported rolling 30 days"},"as_of":"2026-08-03","method":"total30d.","scope":{"product":"blockchain network","chains":[]},"formula":null,"raw_input_ids":[],"claim_ids":["claim:rootstock:metric:revenue-30d"],"quality_flags":["gross_fees_not_profit","methodology_requires_review"]}],"events":[{"id":"event:rootstock:peak-tvl","type":"market_event","date":"2025-10-07","description":"Rootstock reached the maximum TVL point in the reviewed series.","claim_ids":["claim:rootstock:event:peak-tvl"]}],"sources":[{"id":"source:rootstock:overview","title":"Rootstock developer portal","url":"https://dev.rootstock.io/","publisher":"Rootstock","published_at":null,"accessed_at":"2026-08-03T19:45:03.000Z","archive_url":null,"tier":"B","role":"primary","access_state":"reachable","checked_at":"2026-08-03T19:45:03.000Z","content_hash":null,"evidence_locator":"Current EVM sidechain, merge-mining, rBTC and PowPeg descriptions."},{"id":"source:rootstock:federation","title":"PowPeg federation trust discussion","url":"https://research.rsk.dev/t/federation-trust/315","publisher":"Rootstock Research","published_at":null,"accessed_at":"2026-08-03T19:45:03.000Z","archive_url":null,"tier":"B","role":"primary","access_state":"reachable","checked_at":"2026-08-03T19:45:03.000Z","content_hash":null,"evidence_locator":"Operator research discussion of the federation label and inability to prove private keys were not copied."},{"id":"source:rootstock:rskip383","title":"RSKIP-383 PowPeg composition changes","url":"https://ips.rootstock.io/IPs/RSKIP383.html","publisher":"Rootstock","published_at":null,"accessed_at":"2026-08-03T19:45:03.000Z","archive_url":null,"tier":"B","role":"primary","access_state":"reachable","checked_at":"2026-08-03T19:45:03.000Z","content_hash":null,"evidence_locator":"Adopted PowPeg composition-change process."},{"id":"source:rootstock:rskip419","title":"RSKIP-419 PowPeg spendability validation","url":"https://ips.rootstock.io/IPs/RSKIP419.html","publisher":"Rootstock","published_at":null,"accessed_at":"2026-08-03T19:45:03.000Z","archive_url":null,"tier":"B","role":"primary","access_state":"reachable","checked_at":"2026-08-03T19:45:03.000Z","content_hash":null,"evidence_locator":"Adopted validation change for PowPeg spendability."},{"id":"source:rootstock:union","title":"Union: a trust-minimized bridge for Rootstock","url":"https://arxiv.org/abs/2501.07435","publisher":"Rootstock Research","published_at":null,"accessed_at":"2026-08-03T19:45:03.000Z","archive_url":null,"tier":"B","role":"primary","access_state":"reachable","checked_at":"2026-08-03T19:45:03.000Z","content_hash":null,"evidence_locator":"Research design for a future BitVMX-based bridge; not evidence of production deployment."},{"id":"source:rootstock:spark","title":"Rootstock EVM sidechain analysis","url":"https://www.spark.money/research/rootstock-rsk-evm-bitcoin-analysis","publisher":"Spark","published_at":null,"accessed_at":"2026-08-03T19:45:03.000Z","archive_url":null,"tier":"B","role":"independent","access_state":"reachable","checked_at":"2026-08-03T19:45:03.000Z","content_hash":null,"evidence_locator":"Independent current analysis of the PowPeg threshold and Union testnet/roadmap boundary."},{"id":"source:rootstock:tvl","title":"Rootstock historical TVL API","url":"https://api.llama.fi/v2/historicalChainTvl/Rootstock","publisher":"DefiLlama","published_at":null,"accessed_at":"2026-08-03T19:45:03.000Z","archive_url":null,"tier":"B","role":"independent","access_state":"reachable","checked_at":"2026-08-03T19:45:03.000Z","content_hash":null,"evidence_locator":"Latest and maximum points in the returned daily TVL series."},{"id":"source:rootstock:volume","title":"Rootstock DEX volume API","url":"https://api.llama.fi/overview/dexs/Rootstock?dataType=dailyVolume","publisher":"DefiLlama","published_at":null,"accessed_at":"2026-08-03T19:45:03.000Z","archive_url":null,"tier":"B","role":"independent","access_state":"reachable","checked_at":"2026-08-03T19:45:03.000Z","content_hash":null,"evidence_locator":"total30d and change_1m fields."},{"id":"source:rootstock:fees","title":"Rootstock fees API","url":"https://api.llama.fi/overview/fees/Rootstock?dataType=dailyFees","publisher":"DefiLlama","published_at":null,"accessed_at":"2026-08-03T19:45:03.000Z","archive_url":null,"tier":"B","role":"independent","access_state":"reachable","checked_at":"2026-08-03T19:45:03.000Z","content_hash":null,"evidence_locator":"total30d field."},{"id":"source:rootstock:revenue","title":"Rootstock revenue API","url":"https://api.llama.fi/overview/fees/Rootstock?dataType=dailyRevenue","publisher":"DefiLlama","published_at":null,"accessed_at":"2026-08-03T19:45:03.000Z","archive_url":null,"tier":"B","role":"independent","access_state":"reachable","checked_at":"2026-08-03T19:45:03.000Z","content_hash":null,"evidence_locator":"total30d field."},{"id":"source:rootstock:stables","title":"Stablecoin supply by chain API","url":"https://stablecoins.llama.fi/stablecoinchains","publisher":"DefiLlama","published_at":null,"accessed_at":"2026-08-03T19:45:03.000Z","archive_url":null,"tier":"B","role":"independent","access_state":"reachable","checked_at":"2026-08-03T19:45:03.000Z","content_hash":null,"evidence_locator":"Rootstock row and peggedUSD field."}],"claims":[{"id":"claim:rootstock:status","field_path":"status.operating_state","assertion":"Rootstock was operating at the review date.","value":"operating","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:rootstock:overview","source:rootstock:tvl","source:rootstock:spark"],"evidence_locator":"Current developer documentation, independent analysis and nonzero capital show an operating sidechain.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:rootstock:outcome","field_path":"outcome.label","assertion":"Rootstock is classified declining as of 2026-08-03.","value":"declining","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:rootstock:tvl","source:rootstock:volume","source:rootstock:fees","source:rootstock:revenue","source:rootstock:spark"],"evidence_locator":"Capital, activity, economics and current bridge assumptions were reviewed together.","support_direction":"supports","note":"Analyst lifecycle classification; current metrics do not prove a single cause.","review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:rootstock:section:what_it_is:1","field_path":"analysis.sections.what_it_is.body","assertion":"Rootstock is an EVM-compatible merge-mined sidechain using rBTC for gas.","value":"Rootstock is an EVM-compatible merge-mined sidechain using rBTC for gas.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:rootstock:overview","source:rootstock:spark"],"evidence_locator":"Current architecture descriptions.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:rootstock:section:what_it_is:2","field_path":"analysis.sections.what_it_is.body","assertion":"PowPeg custody assumptions are separate from merge-mined block security.","value":"PowPeg custody assumptions are separate from merge-mined block security.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:rootstock:federation","source:rootstock:spark"],"evidence_locator":"Federation and independent bridge analysis.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:rootstock:section:what_happened:1","field_path":"analysis.sections.what_happened.body","assertion":"Rootstock TVL fell from $283,447,916 to $71,082,992.","value":"Rootstock TVL fell from $283,447,916 to $71,082,992.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:rootstock:tvl"],"evidence_locator":"Maximum and latest historical series points.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:rootstock:section:what_happened:2","field_path":"analysis.sections.what_happened.body","assertion":"Thirty-day DEX volume fell 36.55%, and provider-reported revenue was $1.","value":"volume 44050794; change -36.55%; revenue 1","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:rootstock:volume","source:rootstock:revenue"],"evidence_locator":"Provider change_1m and total30d fields.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:rootstock:section:why_this_outcome:1","field_path":"analysis.sections.why_this_outcome.body","assertion":"EVM compatibility and rBTC created a durable Bitcoin DeFi niche.","value":"EVM compatibility and rBTC created a durable Bitcoin DeFi niche.","as_of":"2026-08-03","confidence":"medium","kind":"inference","source_ids":["source:rootstock:overview","source:rootstock:spark"],"evidence_locator":"Current product and independent market analysis.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:rootstock:section:why_this_outcome:2","field_path":"analysis.sections.why_this_outcome.body","assertion":"Bridge trust and weak current economics limit the security and growth story.","value":"Bridge trust and weak current economics limit the security and growth story.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:rootstock:federation","source:rootstock:tvl","source:rootstock:revenue"],"evidence_locator":"Current custody boundary and economic observations.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:rootstock:section:strategic_choices:1","field_path":"analysis.sections.strategic_choices.body","assertion":"Rootstock chose merge mining, rBTC gas and a threshold PowPeg.","value":"Rootstock chose merge mining, rBTC gas and a threshold PowPeg.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:rootstock:overview","source:rootstock:federation","source:rootstock:spark"],"evidence_locator":"Current network and bridge design.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:rootstock:section:strategic_choices:2","field_path":"analysis.sections.strategic_choices.body","assertion":"Union remains research or testnet work, not the live production bridge.","value":"Union remains research or testnet work, not the live production bridge.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:rootstock:union","source:rootstock:spark"],"evidence_locator":"Research paper and independent deployment boundary.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:rootstock:section:operating_model:1","field_path":"analysis.sections.operating_model.body","assertion":"Rootstock block production uses merge mining while PowPeg uses threshold functionaries.","value":"Rootstock block production uses merge mining while PowPeg uses threshold functionaries.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:rootstock:overview","source:rootstock:spark"],"evidence_locator":"Current consensus and bridge descriptions.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:rootstock:section:operating_model:2","field_path":"analysis.sections.operating_model.body","assertion":"PowPeg improvements do not provide users a unilateral exit from the current peg.","value":"PowPeg improvements do not provide users a unilateral exit from the current peg.","as_of":"2026-08-03","confidence":"high","kind":"unknown","source_ids":["source:rootstock:rskip383","source:rootstock:rskip419","source:rootstock:federation"],"evidence_locator":"Adopted changes and federation limitations.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:rootstock:section:token_and_value_capture:1","field_path":"analysis.sections.token_and_value_capture.body","assertion":"rBTC is the gas asset, while RIF is not the chain gas or consensus token.","value":"rBTC is the gas asset, while RIF is not the chain gas or consensus token.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:rootstock:overview","source:rootstock:spark"],"evidence_locator":"Current network and ecosystem boundary.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:rootstock:section:token_and_value_capture:2","field_path":"analysis.sections.token_and_value_capture.body","assertion":"Provider-reported chain revenue is not total app, miner or ecosystem income.","value":"Provider-reported chain revenue is not total app, miner or ecosystem income.","as_of":"2026-08-03","confidence":"high","kind":"unknown","source_ids":["source:rootstock:fees","source:rootstock:revenue"],"evidence_locator":"Aggregate provider fields.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:rootstock:section:counterfactual:1","field_path":"analysis.sections.counterfactual.body","assertion":"A separate validator token would create direct incentives while weakening Bitcoin alignment.","value":"A separate validator token would create direct incentives while weakening Bitcoin alignment.","as_of":"2026-08-03","confidence":"medium","kind":"counterfactual","source_ids":["source:rootstock:overview","source:rootstock:spark"],"evidence_locator":"Current merge-mined design.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:rootstock:section:counterfactual:2","field_path":"analysis.sections.counterfactual.body","assertion":"A production trust-minimized bridge could reduce PowPeg dependence, but Union is not there yet.","value":"A production trust-minimized bridge could reduce PowPeg dependence, but Union is not there yet.","as_of":"2026-08-03","confidence":"medium","kind":"counterfactual","source_ids":["source:rootstock:union","source:rootstock:spark"],"evidence_locator":"Roadmap versus current deployment.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:rootstock:section:risks_and_unknowns:1","field_path":"analysis.sections.risks_and_unknowns.body","assertion":"Peg, miner, contract, liquidity and competition risks remain material.","value":"Peg, miner, contract, liquidity and competition risks remain material.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:rootstock:federation","source:rootstock:spark","source:rootstock:tvl"],"evidence_locator":"Current bridge and market conditions.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:rootstock:section:risks_and_unknowns:2","field_path":"analysis.sections.risks_and_unknowns.body","assertion":"Functionary ownership, unilateral exits, user cohorts and revenue methodology remain unresolved.","value":"Functionary ownership, unilateral exits, user cohorts and revenue methodology remain unresolved.","as_of":"2026-08-03","confidence":"high","kind":"unknown","source_ids":["source:rootstock:federation","source:rootstock:revenue","source:rootstock:volume"],"evidence_locator":"Reviewed sources omit reconciled answers.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:rootstock:section:lifecycle:1","field_path":"analysis.sections.lifecycle.body","assertion":"Rootstock remains a live, mature Bitcoin sidechain.","value":"Rootstock remains a live, mature Bitcoin sidechain.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:rootstock:overview","source:rootstock:spark","source:rootstock:tvl"],"evidence_locator":"Current operation and capital.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:rootstock:section:lifecycle:2","field_path":"analysis.sections.lifecycle.body","assertion":"Capital, volume and revenue observations support a declining call.","value":"Capital, volume and revenue observations support a declining call.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:rootstock:tvl","source:rootstock:volume","source:rootstock:revenue"],"evidence_locator":"Peak-to-current activity and economics.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:rootstock:section:outlook_and_watch:1","field_path":"analysis.sections.outlook_and_watch.body","assertion":"Stable demand, reconciled economics and a safer production bridge would strengthen the outlook.","value":"Stable demand, reconciled economics and a safer production bridge would strengthen the outlook.","as_of":"2026-08-03","confidence":"medium","kind":"inference","source_ids":["source:rootstock:tvl","source:rootstock:fees","source:rootstock:revenue","source:rootstock:union"],"evidence_locator":"Current baseline and future bridge work.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:rootstock:section:o