INSERT INTO chain_analysis (chain, take, sentiment, trend, updated_at, sources, profile)
VALUES (
  'Sonic',
  'Sonic offered faster execution, grants and a direct migration path to Fantom’s community. That created a strong early capital cycle, but did not retain most liquidity or trading. The migration also split attention between Opera and Sonic, while new S issuance expanded beyond the initial 1:1 conversion story. Fee Monetization can help applications, yet it cannot create users by itself. Current metrics show a shipped migration with weak retention.',
  'bearish',
  'Sonic is operating but declining. The migration, token, validators and FeeM system are live, and the chain still holds stablecoins and trading activity. Yet TVL is 98.69% below peak, monthly volume fell 65.61% and S is 97.79% below its high. The next phase is proving that the new chain can retain applications and users after the Fantom migration and major issuance programs.',
  '2026-08-03',
  '[{"id":"source:sonic:migration","title":"Sonic migration overview","url":"https://docs.soniclabs.com/migration/overview","publisher":"Sonic Labs","source_role":"primary","tier":"B","checked_at":"2026-08-03T19:45:03.000Z","evidence_locator":"Launch date, FTM-to-S conversion phases and Fantom Opera continuation."},{"id":"source:sonic:token","title":"S token documentation","url":"https://docs.soniclabs.com/sonic/s-token","publisher":"Sonic Labs","source_role":"primary","tier":"B","checked_at":"2026-08-03T19:45:03.000Z","evidence_locator":"Current S supply, utility, airdrop, annual issuance, block rewards and Sonic USA issuance."},{"id":"source:sonic:feem","title":"Fee Monetization","url":"https://docs.soniclabs.com/funding/fee-monetization","publisher":"Sonic Labs","source_role":"primary","tier":"B","checked_at":"2026-08-03T19:45:03.000Z","evidence_locator":"Current registered-app and validator fee split."},{"id":"source:sonic:faq","title":"Sonic FAQ","url":"https://docs.soniclabs.com/sonic/faq","publisher":"Sonic Labs","source_role":"primary","tier":"B","checked_at":"2026-08-03T19:45:03.000Z","evidence_locator":"Current network, migration and token answers."},{"id":"source:sonic:infra","title":"Sonic post-migration infrastructure update","url":"https://blog.soniclabs.com/sonic-labs-post-migration-infrastructure-update/","publisher":"Sonic Labs","published_at":"2026-02-02","source_role":"primary","tier":"B","checked_at":"2026-08-03T19:45:03.000Z","evidence_locator":"Dated infrastructure changes and stated balance/supply boundary."},{"id":"source:sonic:21shares","title":"FTM to S migration FAQ","url":"https://cdn.21shares.com/uploads/current-documents/products/misc/FTM%3AS_MigrationFAQ.pdf","publisher":"21Shares","source_role":"independent","tier":"B","checked_at":"2026-08-03T19:45:03.000Z","evidence_locator":"Independent description of 1:1 migration and post-genesis supply-growth boundary."},{"id":"source:sonic:tvl","title":"Sonic historical TVL API","url":"https://api.llama.fi/v2/historicalChainTvl/Sonic","publisher":"DefiLlama","source_role":"independent","tier":"B","checked_at":"2026-08-03T19:45:03.000Z","evidence_locator":"Latest and maximum points in the returned daily TVL series."},{"id":"source:sonic:volume","title":"Sonic DEX volume API","url":"https://api.llama.fi/overview/dexs/Sonic?dataType=dailyVolume","publisher":"DefiLlama","source_role":"independent","tier":"B","checked_at":"2026-08-03T19:45:03.000Z","evidence_locator":"total30d and change_1m fields."},{"id":"source:sonic:fees","title":"Sonic fees API","url":"https://api.llama.fi/overview/fees/Sonic?dataType=dailyFees","publisher":"DefiLlama","source_role":"independent","tier":"B","checked_at":"2026-08-03T19:45:03.000Z","evidence_locator":"total30d field."},{"id":"source:sonic:revenue","title":"Sonic revenue API","url":"https://api.llama.fi/overview/fees/Sonic?dataType=dailyRevenue","publisher":"DefiLlama","source_role":"independent","tier":"B","checked_at":"2026-08-03T19:45:03.000Z","evidence_locator":"total30d field."},{"id":"source:sonic:stables","title":"Stablecoin supply by chain API","url":"https://stablecoins.llama.fi/stablecoinchains","publisher":"DefiLlama","source_role":"independent","tier":"B","checked_at":"2026-08-03T19:45:03.000Z","evidence_locator":"Sonic row and peggedUSD field."},{"id":"source:sonic:market","title":"Sonic token market data","url":"https://api.coingecko.com/api/v3/coins/sonic-3","publisher":"CoinGecko","source_role":"aggregator","tier":"B","checked_at":"2026-08-03T19:45:03.000Z","evidence_locator":"current price, market cap, FDV and all-time-high fields."}]',
  '{"canonical_profile":{"schema":"chaindump-entity-profile","version":1,"identity":{"id":"blockchain:sonic","type":"blockchain","slug":"sonic","name":"Sonic","aliases":[]},"classification":{"subtype":"EVM L1","tags":["evm","fantom_migration","s_token","fee_monetization"],"chains":["Sonic"],"jurisdictions":[]},"status":{"operating_state":"operating","as_of":"2026-08-03","claim_ids":["claim:sonic:status"]},"outcome":{"label":"declining","as_of":"2026-08-03","rule_id":"blockchain-lifecycle-v1","confidence":"high","claim_ids":["claim:sonic:outcome"]},"analysis":{"sections":{"what_it_is":{"body":"Sonic is an EVM Layer 1 launched by the team behind Fantom. FTM holders can migrate one-way into S at 1:1, and S pays gas, secures validators and supports governance. Sonic is not merely a renamed Fantom ledger: it is a new chain with its own activity, allocations and later token issuance. Fantom Opera still exists, although new development moved toward Sonic.","as_of":"2026-08-03","claim_ids":["claim:sonic:section:what_it_is:1","claim:sonic:section:what_it_is:2"]},"what_happened":{"body":"Sonic launched on December 18, 2024 and attracted more than $1.14 billion of TVL by May 2025. TVL later fell to $14.99 million, a 98.69% drawdown. Dollar stablecoins were $134.73 million. Thirty-day DEX volume was $24.95 million, down 65.61% from the prior provider comparison; fees were $129,818.62 and provider-reported retained revenue was $80,796.92.","as_of":"2026-08-03","claim_ids":["claim:sonic:section:what_happened:1","claim:sonic:section:what_happened:2"]},"why_this_outcome":{"body":"Sonic offered faster execution, grants and a direct migration path to Fantom’s community. That created a strong early capital cycle, but did not retain most liquidity or trading. The migration also split attention between Opera and Sonic, while new S issuance expanded beyond the initial 1:1 conversion story. Fee Monetization can help applications, yet it cannot create users by itself. Current metrics show a shipped migration with weak retention.","as_of":"2026-08-03","claim_ids":["claim:sonic:section:why_this_outcome:1","claim:sonic:section:why_this_outcome:2"]},"strategic_choices":{"body":"Sonic chose a new chain and token migration instead of upgrading Fantom Opera in place. It kept a 1:1 FTM conversion, then added airdrop, ecosystem, annual and Sonic USA issuance. It also gives registered applications 90% of eligible gas fees through Fee Monetization, leaving 10% for validators. These choices reward apps and fund growth, while creating supply, accounting and migration complexity.","as_of":"2026-08-03","claim_ids":["claim:sonic:section:strategic_choices:1","claim:sonic:section:strategic_choices:2"]},"operating_model":{"body":"Validators stake S and process Sonic transactions. S is used for gas and governance, while registered applications can claim most eligible gas fees through FeeM. Fantom Opera continues separately, so balances, transactions and TVL from the old chain are not Sonic metrics. A 2026 infrastructure update changed operational components without changing user balances or supply; that update is not a new token migration.","as_of":"2026-08-03","claim_ids":["claim:sonic:section:operating_model:1","claim:sonic:section:operating_model:2"]},"token_and_value_capture":{"body":"S pays gas, secures validators and supports governance. The current supply is about 3.8 billion after the base migration, airdrop, annual funding and a 472.37 million S Sonic USA issuance. CoinGecko observed S at $0.02276235 with an $88.44 million market capitalization and fully diluted value, 97.79% below its recorded high. Gross chain fees are split with applications, so they are not all validator or foundation revenue.","as_of":"2026-08-03","claim_ids":["claim:sonic:section:token_and_value_capture:1","claim:sonic:section:token_and_value_capture:2"]},"counterfactual":{"body":"Sonic could have upgraded Opera in place, preserving one ledger and token history while carrying more legacy constraints. It could have capped S at the migrated FTM supply, reducing dilution but removing funding for airdrops, ecosystem plans and Sonic USA. It could also have kept all gas fees with validators, simplifying economics while weakening the application-acquisition pitch.","as_of":"2026-08-03","claim_ids":["claim:sonic:section:counterfactual:1","claim:sonic:section:counterfactual:2"]},"risks_and_unknowns":{"body":"The main risks are weak retained liquidity, token dilution, fragmented Fantom/Sonic activity, validator concentration and dependence on incentives. Stablecoin supply materially exceeds DeFi TVL, so it should not be treated as equivalent productive capital. We lack repeat-user cohorts, a full S supply and unlock reconciliation, FeeM concentration by app, validator beneficial ownership and net foundation economics after grants and issuances.","as_of":"2026-08-03","claim_ids":["claim:sonic:section:risks_and_unknowns:1","claim:sonic:section:risks_and_unknowns:2"]},"lifecycle":{"body":"Sonic is operating but declining. The migration, token, validators and FeeM system are live, and the chain still holds stablecoins and trading activity. Yet TVL is 98.69% below peak, monthly volume fell 65.61% and S is 97.79% below its high. The next phase is proving that the new chain can retain applications and users after the Fantom migration and major issuance programs.","as_of":"2026-08-03","claim_ids":["claim:sonic:section:lifecycle:1","claim:sonic:section:lifecycle:2"]},"outlook_and_watch":{"body":"The base case is a smaller active L1 that retains parts of the Fantom ecosystem but struggles to rebuild peak liquidity. The call improves if TVL stabilizes, repeat users grow, FeeM supports several durable apps and S issuance slows relative to fees. Watch FTM conversions, S supply, validator stake, stablecoin deployment, app fee concentration, token unlocks and cross-chain TVL accounting. The call worsens if new issuance funds activity that disappears when rewards stop.","as_of":"2026-08-03","claim_ids":["claim:sonic:section:outlook_and_watch:1","claim:sonic:section:outlook_and_watch:2"]}}},"metrics":[{"id":"metric:sonic:tvl-latest:2026-08-03","dimension":"tvl","label":"TVL","value":14990537,"unit":"usd","currency":"USD","window":{"start":null,"end":"2026-08-03","definition":"latest point"},"as_of":"2026-08-03","method":"Latest historicalChainTvl point.","scope":{"product":"blockchain network","chains":[]},"formula":null,"raw_input_ids":[],"claim_ids":["claim:sonic:metric:tvl-latest"],"quality_flags":[]},{"id":"metric:sonic:stablecoins-latest:2026-08-03","dimension":"stablecoin_supply","label":"Dollar stablecoin supply","value":134732276.02471256,"unit":"usd","currency":"USD","window":{"start":null,"end":"2026-08-03","definition":"latest point"},"as_of":"2026-08-03","method":"peggedUSD field.","scope":{"product":"blockchain network","chains":[]},"formula":null,"raw_input_ids":[],"claim_ids":["claim:sonic:metric:stablecoins-latest"],"quality_flags":[]},{"id":"metric:sonic:dex-volume-30d:2026-08-03","dimension":"dex_spot_volume","label":"DEX volume (30d)","value":24947891.62,"unit":"usd","currency":"USD","window":{"start":null,"end":"2026-08-03","definition":"provider-reported rolling 30 days"},"as_of":"2026-08-03","method":"total30d.","scope":{"product":"blockchain network","chains":[]},"formula":null,"raw_input_ids":[],"claim_ids":["claim:sonic:metric:dex-volume-30d"],"quality_flags":["not_unique_users","fantom_activity_excluded"]},{"id":"metric:sonic:fees-30d:2026-08-03","dimension":"fees","label":"Fees (30d)","value":129818.62,"unit":"usd","currency":"USD","window":{"start":null,"end":"2026-08-03","definition":"provider-reported rolling 30 days"},"as_of":"2026-08-03","method":"total30d.","scope":{"product":"blockchain network","chains":[]},"formula":null,"raw_input_ids":[],"claim_ids":["claim:sonic:metric:fees-30d"],"quality_flags":[]},{"id":"metric:sonic:revenue-30d:2026-08-03","dimension":"protocol_revenue","label":"Protocol revenue (30d)","value":80796.92,"unit":"usd","currency":"USD","window":{"start":null,"end":"2026-08-03","definition":"provider-reported rolling 30 days"},"as_of":"2026-08-03","method":"total30d.","scope":{"product":"blockchain network","chains":[]},"formula":null,"raw_input_ids":[],"claim_ids":["claim:sonic:metric:revenue-30d"],"quality_flags":["gross_fees_not_profit","feem_split_requires_reconciliation"]},{"id":"metric:sonic:token-price:2026-08-03","dimension":"token_price","label":"S price","value":0.02276235,"unit":"usd","currency":"USD","window":{"start":null,"end":"2026-08-03","definition":"latest point"},"as_of":"2026-08-03","method":"current_price.usd.","scope":{"product":"blockchain network","chains":[]},"formula":null,"raw_input_ids":[],"claim_ids":["claim:sonic:metric:token-price"],"quality_flags":[]},{"id":"metric:sonic:token-market-cap:2026-08-03","dimension":"token_market_cap","label":"S market capitalization","value":88439111,"unit":"usd","currency":"USD","window":{"start":null,"end":"2026-08-03","definition":"latest point"},"as_of":"2026-08-03","method":"market_cap.usd.","scope":{"product":"blockchain network","chains":[]},"formula":null,"raw_input_ids":[],"claim_ids":["claim:sonic:metric:token-market-cap"],"quality_flags":[]},{"id":"metric:sonic:token-fdv:2026-08-03","dimension":"token_fdv","label":"S fully diluted value","value":88439111,"unit":"usd","currency":"USD","window":{"start":null,"end":"2026-08-03","definition":"latest point"},"as_of":"2026-08-03","method":"fully_diluted_valuation.usd.","scope":{"product":"blockchain network","chains":[]},"formula":null,"raw_input_ids":[],"claim_ids":["claim:sonic:metric:token-fdv"],"quality_flags":[]}],"events":[{"id":"event:sonic:mainnet","type":"launch","date":"2024-12-18","description":"Sonic mainnet launched with FTM-to-S migration.","claim_ids":["claim:sonic:event:mainnet"]},{"id":"event:sonic:peak-tvl","type":"market_event","date":"2025-05-11","description":"Sonic reached the maximum TVL point in the reviewed series.","claim_ids":["claim:sonic:event:peak-tvl"]},{"id":"event:sonic:sonic-usa","type":"token_issuance","date":"2025-09-04","description":"Sonic issued 472,372,662.8 S for its Sonic USA strategy.","claim_ids":["claim:sonic:event:sonic-usa"]}],"sources":[{"id":"source:sonic:migration","title":"Sonic migration overview","url":"https://docs.soniclabs.com/migration/overview","publisher":"Sonic Labs","published_at":null,"accessed_at":"2026-08-03T19:45:03.000Z","archive_url":null,"tier":"B","role":"primary","access_state":"reachable","checked_at":"2026-08-03T19:45:03.000Z","content_hash":null,"evidence_locator":"Launch date, FTM-to-S conversion phases and Fantom Opera continuation."},{"id":"source:sonic:token","title":"S token documentation","url":"https://docs.soniclabs.com/sonic/s-token","publisher":"Sonic Labs","published_at":null,"accessed_at":"2026-08-03T19:45:03.000Z","archive_url":null,"tier":"B","role":"primary","access_state":"reachable","checked_at":"2026-08-03T19:45:03.000Z","content_hash":null,"evidence_locator":"Current S supply, utility, airdrop, annual issuance, block rewards and Sonic USA issuance."},{"id":"source:sonic:feem","title":"Fee Monetization","url":"https://docs.soniclabs.com/funding/fee-monetization","publisher":"Sonic Labs","published_at":null,"accessed_at":"2026-08-03T19:45:03.000Z","archive_url":null,"tier":"B","role":"primary","access_state":"reachable","checked_at":"2026-08-03T19:45:03.000Z","content_hash":null,"evidence_locator":"Current registered-app and validator fee split."},{"id":"source:sonic:faq","title":"Sonic FAQ","url":"https://docs.soniclabs.com/sonic/faq","publisher":"Sonic Labs","published_at":null,"accessed_at":"2026-08-03T19:45:03.000Z","archive_url":null,"tier":"B","role":"primary","access_state":"reachable","checked_at":"2026-08-03T19:45:03.000Z","content_hash":null,"evidence_locator":"Current network, migration and token answers."},{"id":"source:sonic:infra","title":"Sonic post-migration infrastructure update","url