supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:sonic:section:what_happened:2","field_path":"analysis.sections.what_happened.body","assertion":"TVL fell from $1,140,087,474 to $14,990,537.","value":"TVL fell from $1,140,087,474 to $14,990,537.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:sonic:tvl"],"evidence_locator":"Maximum and latest historical series points.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:sonic:section:why_this_outcome:1","field_path":"analysis.sections.why_this_outcome.body","assertion":"Migration and app incentives produced a launch cycle but did not retain peak capital.","value":"Migration and app incentives produced a launch cycle but did not retain peak capital.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:sonic:migration","source:sonic:feem","source:sonic:tvl"],"evidence_locator":"Product incentives compared with capital history.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:sonic:section:why_this_outcome:2","field_path":"analysis.sections.why_this_outcome.body","assertion":"The reviewed data do not isolate organic demand from migrated or incentivized activity.","value":"The reviewed data do not isolate organic demand from migrated or incentivized activity.","as_of":"2026-08-03","confidence":"high","kind":"unknown","source_ids":["source:sonic:volume","source:sonic:feem"],"evidence_locator":"Aggregate activity and incentive system.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:sonic:section:strategic_choices:1","field_path":"analysis.sections.strategic_choices.body","assertion":"Sonic chose a new L1 with one-way FTM-to-S migration after the first 90 days.","value":"Sonic chose a new L1 with one-wa